ALTER TABLE public.developer_projects ADD COLUMN IF NOT EXISTS commission_config jsonb NOT NULL DEFAULT '{}'::jsonb;
ALTER TABLE public.listings ADD COLUMN IF NOT EXISTS developer_project_id uuid REFERENCES public.developer_projects(id);
ALTER TABLE public.listings ADD COLUMN IF NOT EXISTS developer_unit_key text;
CREATE UNIQUE INDEX IF NOT EXISTS listings_developer_project_unit ON public.listings(developer_project_id,developer_unit_key) WHERE developer_project_id IS NOT NULL;
CREATE OR REPLACE FUNCTION public.developer_fees_valid(_fees jsonb,_deal text,_price numeric) RETURNS boolean LANGUAGE plpgsql IMMUTABLE SET search_path=public AS $$ DECLARE k text; v numeric; c numeric; BEGIN IF _fees IS NULL OR _price IS NULL OR _price<=0 THEN RETURN false; END IF; FOREACH k IN ARRAY ARRAY['form','whatsapp','phone'] LOOP IF jsonb_typeof(_fees->k)<>'number' OR jsonb_typeof(_fees->'caps'->k)<>'number' THEN RETURN false; END IF; v:=(_fees->>k)::numeric; c:=(_fees->'caps'->>k)::numeric; IF v IS NULL OR v<=0 OR c IS NULL OR c<=0 OR c<>trunc(c) THEN RETURN false; END IF; END LOOP; IF jsonb_typeof(_fees->'closing'->'value')<>'number' THEN RETURN false; END IF; v:=(_fees->'closing'->>'value')::numeric; IF v IS NULL OR v<=0 THEN RETURN false; END IF; IF _fees->'closing'->>'type'='percent' THEN RETURN CASE WHEN _deal='rent' THEN v BETWEEN 10 AND 100 ELSE v BETWEEN 0.2 AND 2 END; END IF; RETURN COALESCE(_fees->'closing'->>'type'='fixed',false); EXCEPTION WHEN OTHERS THEN RETURN false; END $$;
CREATE OR REPLACE FUNCTION public.validate_developer_listing_commissions() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE f jsonb; d text; BEGIN IF NEW.is_published AND (NEW.developer_project_id IS NOT NULL OR NEW.features->>'publisher_type'='developer') THEN IF NEW.developer_project_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.developer_projects p WHERE p.id=NEW.developer_project_id AND p.workspace_owner_id=NEW.workspace_owner_id) THEN RAISE EXCEPTION 'developer_project_workspace_mismatch'; END IF; d:=COALESCE(NEW.deal_type,'sale'); f:=jsonb_build_object('form',NEW.affiliate_tier1_amount,'whatsapp',NEW.affiliate_tier2_amount,'phone',NEW.affiliate_tier3_amount,'caps',NEW.contact_options->'lead_daily_limits','closing',jsonb_build_object('type','fixed','value',NEW.affiliate_tier4_amount)); IF NOT public.developer_fees_valid(f,d,NEW.asking_price) THEN RAISE EXCEPTION 'developer_commissions_required'; END IF; END IF; RETURN NEW; END $$;
CREATE TRIGGER zz_validate_developer_commissions BEFORE INSERT OR UPDATE ON public.listings FOR EACH ROW EXECUTE FUNCTION public.validate_developer_listing_commissions();
CREATE OR REPLACE FUNCTION public.publish_developer_project(_project uuid,_unit_key text DEFAULT NULL) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE p public.developer_projects; co public.developers; uid uuid:=auth.uid(); ws uuid:=public.current_workspace_owner(); d text; u jsonb; targets jsonb:='[]'; target jsonb; fees jsonb; key text; pr numeric; listing_id uuid; ids jsonb:='[]'; imgs jsonb; unitname text; BEGIN IF uid IS NULL THEN RAISE EXCEPTION 'auth_required'; END IF; SELECT * INTO p FROM public.developer_projects WHERE id=_project AND workspace_owner_id=ws FOR UPDATE; IF NOT FOUND OR NOT public.ws_current_access(ws) OR NOT(public.has_role(ws,'developer') OR public.has_role(uid,'super_admin')) THEN RAISE EXCEPTION 'project_access_denied'; END IF; SELECT * INTO co FROM public.developers WHERE id=p.developer_id AND workspace_owner_id=ws; d:=CASE WHEN COALESCE(p.source_details->>'deal_type',p.source_details->'manual'->>'deal_type')='rent' THEN 'rent' ELSE 'sale' END;
IF _unit_key IS NULL THEN targets:=jsonb_build_array(jsonb_build_object('key','project','price',p.price_from)); END IF;
FOR u IN SELECT value FROM jsonb_array_elements(p.apartments) LOOP key:=jsonb_build_array(COALESCE(u->>'building_id',''),u->>'source_unit_id')::text; IF _unit_key IS NULL OR (_unit_key::jsonb=key::jsonb) THEN targets:=targets||jsonb_build_array(jsonb_build_object('key',key,'unit',u,'price',COALESCE(NULLIF(u->>'price','')::numeric,p.price_from))); END IF; END LOOP;
IF jsonb_array_length(targets)=0 THEN RAISE EXCEPTION 'unit_not_found'; END IF;
FOR target IN SELECT value FROM jsonb_array_elements(targets) LOOP key:=target->>'key'; u:=target->'unit'; fees:=CASE WHEN key='project' THEN p.commission_config->'defaults' ELSE COALESCE(p.commission_config->'overrides'->(jsonb_build_array(COALESCE(u->>'building_id',''),u->>'source_unit_id')::text),p.commission_config->'overrides'->replace(jsonb_build_array(COALESCE(u->>'building_id',''),u->>'source_unit_id')::text,', ',','),p.commission_config->'defaults') END; pr:=(target->>'price')::numeric; IF NOT public.developer_fees_valid(fees,d,pr) THEN RAISE EXCEPTION 'developer_commissions_required: %',key; END IF;
unitname:=CASE WHEN key='project' THEN p.name ELSE p.name||' · '||COALESCE(u->>'rooms','')||' חדרים'||CASE WHEN NULLIF(u->>'building_name','') IS NOT NULL THEN ' · בניין '||(u->>'building_name') ELSE '' END END; imgs:=CASE WHEN jsonb_typeof(u->'images')='array' AND jsonb_array_length(u->'images')>0 THEN u->'images' ELSE p.images END;
INSERT INTO public.listings(user_id,workspace_owner_id,slug,property_title,description,long_description,asking_price,city,neighborhood,address,deal_type,rooms,sqm,floor,image_url,media_photos,project_name,source,status,is_published,affiliate_enabled,affiliate_approved_at,affiliate_tier1_amount,affiliate_tier2_amount,affiliate_tier3_type,affiliate_tier3_amount,affiliate_tier4_type,affiliate_tier4_amount,features,contact_options,developer_project_id,developer_unit_key)
VALUES(uid,ws,'project-'||p.id::text||'-'||md5(key),unitname,COALESCE(p.description,''),COALESCE(p.description,''),pr,p.city,p.neighborhood,p.address,d,NULLIF(u->>'rooms','')::numeric,NULLIF(u->>'size_sqm','')::numeric,CASE WHEN u->>'floor'~'^-?[0-9]+$' THEN (u->>'floor')::integer ELSE NULL END,COALESCE(imgs->>0,p.image_url),imgs,p.name,'manual','live',true,true,now(),(fees->>'form')::numeric,(fees->>'whatsapp')::numeric,'fixed',(fees->>'phone')::numeric,'fixed',CASE WHEN fees->'closing'->>'type'='percent' THEN round(pr*(fees->'closing'->>'value')::numeric/100,2) ELSE (fees->'closing'->>'value')::numeric END,jsonb_build_object('publisher_type','developer','property_type',COALESCE(u->>'type','דירה'),'deal_closing_commission',fees->'closing','amenity_labels',COALESCE(p.source_details->'manual'->'amenities','[]'::jsonb),'developer_unit_details',COALESCE(u,'{}'::jsonb)),jsonb_build_object('lead_daily_limits',fees->'caps','whatsapp',true,'phone',true,'form',true),p.id,key)
ON CONFLICT(developer_project_id,developer_unit_key) WHERE developer_project_id IS NOT NULL DO UPDATE SET property_title=EXCLUDED.property_title,description=EXCLUDED.description,long_description=EXCLUDED.long_description,asking_price=EXCLUDED.asking_price,city=EXCLUDED.city,neighborhood=EXCLUDED.neighborhood,address=EXCLUDED.address,deal_type=EXCLUDED.deal_type,rooms=EXCLUDED.rooms,sqm=EXCLUDED.sqm,floor=EXCLUDED.floor,image_url=EXCLUDED.image_url,media_photos=EXCLUDED.media_photos,is_published=true,status='live',affiliate_enabled=true,affiliate_tier1_amount=EXCLUDED.affiliate_tier1_amount,affiliate_tier2_amount=EXCLUDED.affiliate_tier2_amount,affiliate_tier3_amount=EXCLUDED.affiliate_tier3_amount,affiliate_tier4_type=EXCLUDED.affiliate_tier4_type,affiliate_tier4_amount=EXCLUDED.affiliate_tier4_amount,features=CASE WHEN jsonb_typeof(listings.features)='object' THEN listings.features ELSE '{}'::jsonb END||EXCLUDED.features,contact_options=listings.contact_options||EXCLUDED.contact_options RETURNING id INTO listing_id; ids:=ids||jsonb_build_array(listing_id); END LOOP; RETURN jsonb_build_object('ok',true,'listing_ids',ids); END $$;
REVOKE ALL ON FUNCTION public.publish_developer_project(uuid,text) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.publish_developer_project(uuid,text) TO authenticated,service_role;
REVOKE ALL ON FUNCTION public.developer_fees_valid(jsonb,text,numeric) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.developer_fees_valid(jsonb,text,numeric) TO authenticated,service_role;
COMMENT ON COLUMN public.developer_projects.commission_config IS 'Workspace-owned defaults plus explicit building/unit overrides; never scrape over authored fees.';